\label{result: delyon and hu result}
    Let $X$ be the solution of \eqref{eq: BM SDE on Lie group}. The SDE \eqref{eq: guided diffusion sde} yields a strong solution on $[0,T)$ and satisfies $\lim_{t\uparrow T} Y_t = v$ almost surely. Moreover, the conditional expectation of $X$ given $X_T=v$ is
    \begin{equation}
        \mathbb{E}[f(X)|X_T = v] = C \mathbb{E}\left[f(Y) \varphi_T\right],
    \end{equation}
    for every $\mathcal{F}_t$-measurable non-negative function $f$ on $G$, $t<T$, where $\varphi_t$ is given in \eqref{eq: psi and phi function}.

Let $\{D_n\}_{n=1}^{\infty}$ be an exhaustion of $G$, that is, the sequence consists of open, relatively compact subsets of $M$ such that $\bar{D}_n \subseteq D_{n+1}$ and $G = \bigcup_{n=1}^{\infty} D_n$. Furthermore, let $\tau_{D_n}$ denote the first exit time of $Y$ from $D_n$, then from \eqref{eq: mean squared radial bound} we have that the sequence 
$
	\bigl(\mathbb{E} [1_{\{t < \tau_{D_n}\}} r_v^2(Y_t)]\bigr)_{n=1}				^{\infty}
$
is non-decreasing and bounded, hence from the monotone convergence theorem, it has a limit which is bounded by the right-hand side of \eqref{eq: mean squared radial bound}. Applying Jensen's inequality to the left-hand side of \eqref{eq: mean squared radial bound} 
\begin{equation*}
	\mathbb{E} [ r_v(Y_t)] \leq \left( r^2_v(e) + \nu t\left(\frac{t}{T-t}\right) \right)^{\frac{1}{2}}\left(\frac{T-t}{t}\right) e^{\frac{\lambda t}{2}}.
\end{equation*}
Since obviously $\mathbb{E} [ r_v(Y_T)] = r_v(Y_T)\mathbb{Q}(r_v(Y_T) \neq 0)$, by Fatou's lemma
    $
        \mathbb{E}[r_v(Y_T)] \leq \liminf_{t\rightarrow T} \mathbb{E}[r(Y_t)] = 0,
    $
we conclude that $r(Y_t) \rightarrow 0$, $\mathbb{Q}$-almost surely.

\label{result: lemma of conditional expectation}
    Let $0 < t_1 <t_2< \dots < t_N <T$ and $h$ be a continuous bounded function function on $G^N$. With $\psi_t$ as in \eqref{eq: psi and phi function}, then
    \begin{equation}
        \lim_{t \rightarrow T} \frac{\mathbb{E}\left[h\left(X_{t_1},X_{t_2},\dots, X_{t_N}\right)\psi_t\right]}{\mathbb{E}[\psi_t]} = \mathbb{E}\left[h\left(X_{t_1},X_{t_2},\dots, X_{t_N}\right)|X_T =v\right].
    \end{equation}

The proof is similar to that of \cite[Lemma 7]{delyon_simulation_2006}. Let $(U,\phi)$ be a normal chart centered at $v \in G$. First, since the cut locus of any complete connected manifold has (volume) measure zero, we can integrate indifferently in any normal chart. For any $t \in (t_N,T)$ we have
	\begin{equation}
		\mathbb{E}[h(x_{t_1},...,x_{t_N})\psi_t] = \int_G \Phi_h(t,z)e^{-\frac{r_v(z)^2}{2(T-t)}}d\operatorname{Vol}(z)
	\end{equation}
where $d\operatorname{Vol}(z)= \sqrt{\det(A(z))}dz$ denotes the volume measure on $G$, $dz$ the Lebesgue measure, and $A$ the metric tensor. Moreover,
	\begin{equation*}
		\Phi_h(t,z) =
		 \int_{G^N}	h(z_1,...,z_N)p(t_1,u,z_1)\dots p(t-t_N,z_N,z)d			\operatorname{Vol}(z_1) \dots d\operatorname{Vol}(z_N),
	\end{equation*}
and of course $\Phi_1(t,z) = p(t,e,z)$. 
Using the normal chart and applying the change of variable $x=(T-t)^{1/2}y$ we get 
\begin{equation*}
	(T-t)^{-\frac{d}{2}} \mathbb{E}[h(x_{t_1},...,x_{t_N})\psi_t]
	\overset{t \rightarrow T}{\rightarrow}  \Phi_h(T,v) \det(A(v))^{\tfrac{d}{2}}\int_{\phi(G)}e^{-\frac{r_v(\phi^{-1}(y))^2}{2}}dy.
\end{equation*}
The conclusion follows from Bayes' formula.
